  assert.equal(totals.total, expectedTotal);
});

test('invoiceTotals includes voucher field', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 0 }],
    voucher: { code: 'SAVE10', amount: 5000 },
  };
  const totals = invoiceTotals(invoice);
  assert.ok('voucher' in totals);
  assert.equal(totals.voucher, 5000);
});

test('invoiceTotals calculates total with voucher', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 0 }],
    voucher: { code: 'SAVE10', amount: 5000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, totals.subtotal - totals.voucher);
});

test('invoiceTotals voucher formula: total = subtotal - discount + vat - voucher', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 10, vatRate: 21 }],
    voucher: { code: 'SAVE10', amount: 5000 },
  };
  const totals = invoiceTotals(invoice);
  const expected = totals.subtotal - totals.discount + totals.vat - totals.voucher;
  assert.equal(totals.total, expected);
});

test('invoiceTotals voucher with no discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
    voucher: { code: 'SAVE20', amount: 10000 },
  };
  const totals = invoiceTotals(invoice);
  const expected = totals.subtotal + totals.vat - totals.voucher;
  assert.equal(totals.total, expected);
});

test('invoiceTotals with multiple invoice components', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, discountPercent: 10, vatRate: 21 },
      { qty: 1, unitPrice: 120000, discountPercent: 5, vatRate: 21 },
    ],
    voucher: { code: 'COMP10', amount: 8000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5 * 8500 + 1 * 120000);
  assert.ok(totals.discount > 0);
  assert.ok(totals.vat > 0);
  assert.ok(totals.voucher > 0);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat - totals.voucher);
});

test('invoiceTotals total clamped at 0 with large voucher', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    voucher: { code: 'BIG', amount: 50000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, 0);
  assert.equal(totals.total >= 0, true);
});

test('invoiceTotals returns all required fields', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.ok('subtotal' in totals);
  assert.ok('discount' in totals);
  assert.ok('vat' in totals);
  assert.ok('voucher' in totals);
  assert.ok('total' in totals);
});

